const a1Lessons = [
  {id:'greetings',title:'Greetings',tamil:'வாழ்த்துகள்',goal:'Greet someone politely and respond naturally.',goalTamil:'ஒருவரை மரியாதையாக வாழ்த்தி, இயல்பாக பதில் சொல்லுங்கள்.',phrases:[['Hello!','வணக்கம்!','A friendly greeting'],['Good morning.','காலை வணக்கம்.','Use before noon'],['How are you?','நீங்கள் எப்படி இருக்கிறீர்கள்?','Ask about someone'],["I'm fine, thank you.",'நான் நலமாக இருக்கிறேன், நன்றி.','A polite reply']],note:'“Hello” works at any time. “Good morning” is normally used before noon.',noteTamil:'“Hello” என்பதை எந்த நேரத்திலும் பயன்படுத்தலாம். “Good morning” பொதுவாக மதியத்திற்கு முன் பயன்படுத்தப்படும்.',question:'You meet your teacher at 9 AM. What do you say?',options:['Good morning, sir.','Good night, sir.'],answer:0,feedback:'Correct! “Good morning” fits 9 AM.'},
  {id:'introductions',title:'Introduce yourself',tamil:'உங்களை அறிமுகப்படுத்துதல்',goal:'Say your name, home town and what you do.',goalTamil:'உங்கள் பெயர், ஊர் மற்றும் நீங்கள் என்ன செய்கிறீர்கள் என்பதைச் சொல்லுங்கள்.',phrases:[["My name is Mani.",'என் பெயர் மணி.','Say your name'],["I'm from Tenkasi.",'நான் தென்காசியைச் சேர்ந்தவன்.','Say your place'],["I'm a student.",'நான் ஒரு மாணவர்.','Say what you do'],['Nice to meet you.','உங்களைச் சந்தித்ததில் மகிழ்ச்சி.','End politely']],note:'Use “I am” or the shorter form “I’m”. Both have the same meaning.',noteTamil:'“I am” அல்லது அதன் சுருக்கமான “I’m” இரண்டையும் பயன்படுத்தலாம்; பொருள் ஒன்றே.',question:'Which is a correct introduction?',options:["I'm from Tenkasi.",'I from Tenkasi.'],answer:0,feedback:'Correct! We need “am”: I am / I’m from Tenkasi.'},
  {id:'pronouns-be',title:'I, you, he & she',tamil:'நான், நீங்கள், அவன், அவள்',goal:'Match basic pronouns with am, is and are.',goalTamil:'அடிப்படை pronouns-ஐ am, is, are உடன் சரியாகப் பயன்படுத்துங்கள்.',phrases:[['I am ready.','நான் தயாராக இருக்கிறேன்.','I + am'],['You are kind.','நீங்கள் அன்பானவர்.','You + are'],['He is my friend.','அவர் என் நண்பர்.','He + is'],['She is a doctor.','அவர் ஒரு மருத்துவர்.','She + is']],note:'Use “am” with I, “are” with you/we/they, and “is” with he/she/it.',noteTamil:'I உடன் “am”, you/we/they உடன் “are”, he/she/it உடன் “is” பயன்படுத்தவும்.',question:'Choose the correct sentence.',options:['She is my sister.','She are my sister.'],answer:0,feedback:'Correct! “She” takes “is”.'},
  {id:'family',title:'Family & people',tamil:'குடும்பம் மற்றும் மனிதர்கள்',goal:'Talk simply about the people in your family.',goalTamil:'உங்கள் குடும்பத்தில் உள்ளவர்களைப் பற்றி எளிமையாகப் பேசுங்கள்.',phrases:[['This is my mother.','இவர் என் அம்மா.','Introduce a person'],['I have one brother.','எனக்கு ஒரு சகோதரர் உள்ளார்.','Talk about family'],['My father is a driver.','என் அப்பா ஓட்டுநர்.','Say a job'],['We live together.','நாங்கள் ஒன்றாக வசிக்கிறோம்.','Talk about your home']],note:'Use “this is” when introducing one person who is near you.',noteTamil:'உங்களுக்கு அருகில் உள்ள ஒருவரை அறிமுகப்படுத்த “this is” பயன்படுத்தவும்.',question:'How do you introduce your brother?',options:['This is my brother.','These is my brother.'],answer:0,feedback:'Correct! Use “this is” for one person.'},
  {id:'routines',title:'Daily routines',tamil:'தினசரி செயல்கள்',goal:'Describe things you do every day.',goalTamil:'நீங்கள் தினமும் செய்யும் செயல்களை விவரியுங்கள்.',phrases:[['I wake up at six.','நான் ஆறு மணிக்கு எழுகிறேன்.','Morning routine'],['I go to work.','நான் வேலைக்குச் செல்கிறேன்.','Daily activity'],['I eat lunch at one.','நான் ஒரு மணிக்கு மதிய உணவு சாப்பிடுகிறேன்.','Time + activity'],['I study English daily.','நான் தினமும் ஆங்கிலம் படிக்கிறேன்.','Learning routine']],note:'Use the simple present for habits and routines: I work, I study, I go.',noteTamil:'பழக்கங்கள் மற்றும் தினசரி செயல்களுக்கு simple present பயன்படுத்தவும்.',question:'Which sentence describes a daily habit?',options:['I study English every day.','I studying English every day.'],answer:0,feedback:'Correct! Use the base verb after “I”.'},
  {id:'questions',title:'Simple questions',tamil:'எளிய கேள்விகள்',goal:'Ask and answer common personal questions.',goalTamil:'பொதுவான தனிப்பட்ட கேள்விகளைக் கேட்டு பதிலளியுங்கள்.',phrases:[["What's your name?",'உங்கள் பெயர் என்ன?','Ask a name'],['Where are you from?','நீங்கள் எங்கிருந்து வருகிறீர்கள்?','Ask a place'],['What do you do?','நீங்கள் என்ன செய்கிறீர்கள்?','Ask work or study'],['Do you speak English?','நீங்கள் ஆங்கிலம் பேசுவீர்களா?','A yes/no question']],note:'Use “where” for a place, “what” for information, and “do” for many action questions.',noteTamil:'இடத்திற்கு “where”, தகவலுக்கு “what”, பல செயல் கேள்விகளுக்கு “do” பயன்படுத்தவும்.',question:'Which question asks about a place?',options:['Where are you from?','What is your name?'],answer:0,feedback:'Correct! “Where” asks about a place.'},
  {id:'time-numbers',title:'Numbers & time',tamil:'எண்கள் மற்றும் நேரம்',goal:'Say basic numbers and tell the time.',goalTamil:'அடிப்படை எண்களையும் நேரத்தையும் சொல்லுங்கள்.',phrases:[["It's seven o'clock.",'ஏழு மணி ஆகிறது.','Exact hour'],["It's half past eight.",'எட்டரை மணி ஆகிறது.','Thirty minutes after'],['My phone number is…','என் தொலைபேசி எண்…','Read digits separately'],['Today is Monday.','இன்று திங்கட்கிழமை.','Say the day']],note:'For phone numbers, say each digit separately. Zero can be “zero” or “oh”.',noteTamil:'தொலைபேசி எண்ணில் ஒவ்வொரு இலக்கத்தையும் தனித்தனியாகச் சொல்லவும்.',question:'8:30 is…',options:["half past eight","half past seven"],answer:0,feedback:'Correct! 8:30 is “half past eight”.'},
  {id:'mini-conversation',title:'First conversation',tamil:'முதல் உரையாடல்',goal:'Use what you learned in one short conversation.',goalTamil:'நீங்கள் கற்றவற்றை ஒரு சிறிய உரையாடலில் பயன்படுத்துங்கள்.',phrases:[['Hello! My name is Mani.','வணக்கம்! என் பெயர் மணி.','Start'],["Hi Mani, I'm Arun.",'ஹாய் மணி, நான் அருண்.','Reply'],['Where are you from?','நீங்கள் எங்கிருந்து வருகிறீர்கள்?','Continue'],["I'm from Tenkasi. Nice to meet you!",'நான் தென்காசியைச் சேர்ந்தவன். சந்தித்ததில் மகிழ்ச்சி!','Finish politely']],note:'A simple conversation needs a greeting, an introduction, one question and a polite ending.',noteTamil:'ஒரு எளிய உரையாடலுக்கு வாழ்த்து, அறிமுகம், ஒரு கேள்வி மற்றும் மரியாதையான முடிவு போதும்.',question:'What is a natural polite ending?',options:['Nice to meet you.','What your name?'],answer:0,feedback:'Correct! “Nice to meet you” is a natural polite ending.'}
];

const a2Lessons = [
  {id:'happening-now',title:'Happening now',tamil:'இப்போது நடப்பவை',goal:'Describe actions happening at this moment.',goalTamil:'இந்த நேரத்தில் நடக்கும் செயல்களை விவரியுங்கள்.',phrases:[["I'm learning English now.",'நான் இப்போது ஆங்கிலம் கற்றுக்கொண்டிருக்கிறேன்.','Action happening now'],['She is cooking dinner.','அவள் இரவு உணவு சமைத்துக்கொண்டிருக்கிறாள்.','She + is + verb-ing'],['They are waiting outside.','அவர்கள் வெளியே காத்திருக்கிறார்கள்.','They + are + verb-ing'],['Are you working today?','நீங்கள் இன்று வேலை செய்கிறீர்களா?','Present continuous question']],note:'Use am/is/are + verb-ing for something happening now or around now.',noteTamil:'இப்போது அல்லது தற்போதைய காலத்தில் நடக்கும் செயலுக்கு am/is/are + verb-ing பயன்படுத்தவும்.',question:'Which action is happening now?',options:['He is talking on the phone.','He talks on the phone every day.'],answer:0,feedback:'Correct! “is talking” shows an action happening now.'},
  {id:'past-events',title:'Yesterday & the past',tamil:'நேற்று மற்றும் கடந்த காலம்',goal:'Talk about completed actions in the past.',goalTamil:'கடந்த காலத்தில் முடிந்த செயல்களைப் பற்றிப் பேசுங்கள்.',phrases:[['I visited my friend yesterday.','நான் நேற்று என் நண்பரைச் சந்தித்தேன்.','Regular past verb'],['We watched a movie.','நாங்கள் ஒரு திரைப்படம் பார்த்தோம்.','Completed action'],['She went to Chennai.','அவள் சென்னைக்குச் சென்றாள்.','Irregular: go → went'],["I didn't work on Sunday.",'நான் ஞாயிற்றுக்கிழமை வேலை செய்யவில்லை.','Negative past']],note:'Use the past form for completed actions. After “did not / didn’t”, use the base verb.',noteTamil:'முடிந்த செயலுக்கு past form பயன்படுத்தவும். “didn’t”க்குப் பிறகு base verb பயன்படுத்தவும்.',question:'Choose the correct past sentence.',options:['I went to the shop.','I goed to the shop.'],answer:0,feedback:'Correct! The past of “go” is “went”.'},
  {id:'future-plans',title:'Plans & future',tamil:'திட்டங்கள் மற்றும் எதிர்காலம்',goal:'Explain plans, intentions and quick decisions.',goalTamil:'திட்டங்கள், நோக்கங்கள் மற்றும் உடனடி முடிவுகளைச் சொல்லுங்கள்.',phrases:[["I'm going to study tonight.",'நான் இன்று இரவு படிக்கப் போகிறேன்.','A planned action'],['We are going to travel.','நாங்கள் பயணம் செய்யப் போகிறோம்.','Shared plan'],["I'll help you.",'நான் உங்களுக்கு உதவுகிறேன்.','Quick decision'],['Will you call me later?','பிறகு என்னை அழைப்பீர்களா?','Future question']],note:'Use “going to” for a plan already decided. Use “will” for a quick decision, offer or prediction.',noteTamil:'முன்பே தீர்மானித்த திட்டத்திற்கு “going to”; உடனடி முடிவு அல்லது உதவிக்கு “will” பயன்படுத்தவும்.',question:'You already planned to study tonight. Choose the best sentence.',options:["I'm going to study tonight.","I study yesterday."],answer:0,feedback:'Correct! “going to” fits an existing future plan.'},
  {id:'shopping',title:'At a shop',tamil:'கடையில்',goal:'Ask for items, quantities and prices politely.',goalTamil:'பொருட்கள், அளவு மற்றும் விலையை மரியாதையாகக் கேளுங்கள்.',phrases:[['How much is this?','இது எவ்வளவு?','Ask the price'],["I'd like a kilo of rice.",'எனக்கு ஒரு கிலோ அரிசி வேண்டும்.','Polite request'],['Do you have any milk?','பால் ஏதாவது இருக்கிறதா?','Ask about availability'],["That's all, thank you.",'அவ்வளவுதான், நன்றி.','Finish the purchase']],note:'Use “How much?” for a price. “I’d like…” is more polite than “I want…”.',noteTamil:'விலை கேட்க “How much?” பயன்படுத்தவும். “I want” விட “I’d like” மரியாதையானது.',question:'Which request is more polite?',options:["I'd like two bottles of water, please.",'Give me two waters.'],answer:0,feedback:'Correct! “I’d like … please” is a polite shop request.'},
  {id:'directions',title:'Places & directions',tamil:'இடங்கள் மற்றும் வழிகாட்டுதல்',goal:'Ask for and understand simple directions.',goalTamil:'எளிய வழிகளை கேட்டுப் புரிந்துகொள்ளுங்கள்.',phrases:[['Where is the bus stand?','பேருந்து நிலையம் எங்கே?','Ask for a place'],['Go straight ahead.','நேராகச் செல்லுங்கள்.','Give a direction'],['Turn left at the signal.','சிக்னலில் இடதுபுறம் திரும்புங்கள்.','A turning instruction'],["It's next to the bank.",'அது வங்கிக்கு அருகில் உள்ளது.','Describe location']],note:'Use “next to” for beside, “opposite” for across from, and “between” for the middle of two places.',noteTamil:'அருகில் “next to”, எதிரில் “opposite”, இரண்டு இடங்களுக்கு நடுவில் “between” பயன்படுத்தவும்.',question:'The pharmacy is beside the bank. Which phrase fits?',options:["It's next to the bank.","It's under the bank."],answer:0,feedback:'Correct! “next to” means beside.'},
  {id:'travel',title:'Travel & transport',tamil:'பயணம் மற்றும் போக்குவரத்து',goal:'Handle basic bus, train and travel conversations.',goalTamil:'பேருந்து, ரயில் மற்றும் பயண உரையாடல்களைச் சமாளியுங்கள்.',phrases:[['What time does the train leave?','ரயில் எத்தனை மணிக்குப் புறப்படும்?','Ask departure time'],['One ticket to Chennai, please.','சென்னைக்கு ஒரு டிக்கெட் தரவும்.','Buy a ticket'],['Which platform is it?','அது எந்த நடைமேடை?','Find the platform'],['How long does it take?','எவ்வளவு நேரம் ஆகும்?','Ask duration']],note:'Transport timetables use the simple present: “The train leaves at six.”',noteTamil:'போக்குவரத்து அட்டவணைக்கு simple present பயன்படுத்தவும்: “The train leaves at six.”',question:'How do you ask about journey duration?',options:['How long does it take?','How many does it take?'],answer:0,feedback:'Correct! “How long” asks about duration.'},
  {id:'work-phone',title:'Work & phone calls',tamil:'வேலை மற்றும் தொலைபேசி அழைப்புகள்',goal:'Use clear, polite English at work and on calls.',goalTamil:'வேலை மற்றும் அழைப்புகளில் தெளிவான, மரியாதையான ஆங்கிலத்தைப் பயன்படுத்துங்கள்.',phrases:[['May I speak to Mr Ravi?','திரு. ரவியுடன் பேசலாமா?','Ask for a person'],["He's in a meeting right now.",'அவர் இப்போது கூட்டத்தில் இருக்கிறார்.','Explain availability'],['Could you say that again?','அதை மீண்டும் சொல்ல முடியுமா?','Ask for repetition'],["I'll call back later.",'நான் பிறகு மீண்டும் அழைக்கிறேன்.','End the call']],note:'“Could you…?” and “May I…?” make requests sound polite and professional.',noteTamil:'“Could you…?” மற்றும் “May I…?” வேண்டுகோளை மரியாதையாகவும் professional-ஆகவும் மாற்றும்.',question:'You did not hear clearly. What should you say?',options:['Could you say that again?','You talk again.'],answer:0,feedback:'Correct! This is a clear and polite request for repetition.'},
  {id:'everyday-challenge',title:'Everyday conversation',tamil:'தினசரி உரையாடல்',goal:'Combine A2 grammar and phrases in a natural conversation.',goalTamil:'A2 grammar மற்றும் phrases-ஐ இயல்பான உரையாடலில் இணைக்கவும்.',phrases:[["What are you doing this weekend?",'இந்த வார இறுதியில் நீங்கள் என்ன செய்கிறீர்கள்?','Ask about a plan'],["I'm going to visit my family.",'நான் என் குடும்பத்தைச் சந்திக்கப் போகிறேன்.','Share a plan'],['How was your trip last week?','கடந்த வாரப் பயணம் எப்படி இருந்தது?','Ask about the past'],['It was great, but the train was late.','அது சிறப்பாக இருந்தது, ஆனால் ரயில் தாமதமானது.','Give detail']],note:'Natural conversation connects present, past and future ideas with short follow-up questions.',noteTamil:'இயல்பான உரையாடல் present, past, future கருத்துகளைச் சிறிய follow-up கேள்விகளால் இணைக்கிறது.',question:'Which question naturally asks about a future plan?',options:['What are you doing this weekend?','What did you do yesterday?'],answer:0,feedback:'Correct! The first question asks about a planned future activity.'}
];

const b1Lessons = [
  {id:'tense-connections',title:'Tenses in real life',tamil:'நிஜ வாழ்க்கையில் காலங்கள்',goal:'Connect past, present and future ideas clearly.',goalTamil:'கடந்த, நிகழ் மற்றும் எதிர்கால கருத்துகளைத் தெளிவாக இணைக்கவும்.',phrases:[['I work in Tenkasi.','நான் தென்காசியில் வேலை செய்கிறேன்.','Present routine'],["I'm working from home today.",'நான் இன்று வீட்டிலிருந்து வேலை செய்கிறேன்.','Temporary present'],['I finished the report yesterday.','நான் நேற்று அறிக்கையை முடித்தேன்.','Completed past'],["I'll send it tomorrow.",'நான் அதை நாளை அனுப்புவேன்.','Future action']],note:'Choose a tense from the time and meaning, not by translating each Tamil word directly.',noteTamil:'ஒவ்வொரு தமிழ் சொல்லையும் நேரடியாக மொழிபெயர்க்காமல், நேரம் மற்றும் பொருளைப் பார்த்து tense தேர்வு செய்யவும்.',question:'Which sentence describes a temporary action today?',options:["I'm working from home today.",'I work from home every day.'],answer:0,feedback:'Correct! Present continuous shows the temporary situation.'},
  {id:'storytelling',title:'Tell a clear story',tamil:'தெளிவாகக் கதை சொல்லுதல்',goal:'Put events in order and make a story easy to follow.',goalTamil:'நிகழ்வுகளை வரிசைப்படுத்தி, கதையை எளிதாகப் புரிய வைக்கவும்.',phrases:[['First, I missed the bus.','முதலில், நான் பேருந்தைத் தவறவிட்டேன்.','Start the sequence'],['Then, I called a taxi.','பிறகு, நான் டாக்ஸியை அழைத்தேன்.','Continue'],['While I was waiting, it rained.','நான் காத்திருந்தபோது மழை பெய்தது.','Background action'],['Finally, I reached the office.','இறுதியாக, நான் அலுவலகத்தை அடைந்தேன்.','Finish the sequence']],note:'Use first, then, after that and finally to guide the listener through events.',noteTamil:'நிகழ்வுகளை கேட்பவர் பின்தொடர first, then, after that, finally பயன்படுத்தவும்.',question:'Which connector usually ends a sequence?',options:['Finally','First'],answer:0,feedback:'Correct! “Finally” introduces the last event.'},
  {id:'opinions-reasons',title:'Opinions & reasons',tamil:'கருத்துகள் மற்றும் காரணங்கள்',goal:'Share an opinion and support it with reasons.',goalTamil:'உங்கள் கருத்தைச் சொல்லி, காரணங்களால் ஆதரிக்கவும்.',phrases:[['In my opinion, this is useful.','என் கருத்தில், இது பயனுள்ளது.','Introduce an opinion'],['I think we should try it.','நாம் அதை முயற்சிக்க வேண்டும் என்று நினைக்கிறேன்.','Make a suggestion'],['The main reason is the cost.','முக்கிய காரணம் செலவு.','Give a reason'],['However, it may take longer.','ஆனால், இதற்கு அதிக நேரம் ஆகலாம்.','Add a contrast']],note:'A strong opinion answer has a clear view, a reason and a short example.',noteTamil:'ஒரு நல்ல opinion பதிலில் தெளிவான கருத்து, காரணம் மற்றும் சிறிய உதாரணம் இருக்கும்.',question:'Which word introduces a contrasting idea?',options:['However','Because'],answer:0,feedback:'Correct! “However” introduces contrast.'},
  {id:'modals-advice',title:'Advice & possibility',tamil:'ஆலோசனை மற்றும் சாத்தியம்',goal:'Use modal verbs for advice, rules and possibility.',goalTamil:'ஆலோசனை, விதி மற்றும் சாத்தியத்திற்கு modal verbs பயன்படுத்தவும்.',phrases:[['You should check the details.','நீங்கள் விவரங்களைச் சரிபார்க்க வேண்டும்.','Advice'],['You must wear a helmet.','நீங்கள் கட்டாயம் ஹெல்மெட் அணிய வேண்டும்.','Strong rule'],['It might rain later.','பிறகு மழை பெய்யலாம்.','Possibility'],['Could you help me?','நீங்கள் எனக்கு உதவ முடியுமா?','Polite request']],note:'Should gives advice, must expresses obligation, and might shows an uncertain possibility.',noteTamil:'Should ஆலோசனை, must கட்டாயம், might உறுதியில்லாத சாத்தியம் காட்டும்.',question:'Which sentence gives advice?',options:['You should rest today.','You must be over eighteen.'],answer:0,feedback:'Correct! “should” commonly gives advice.'},
  {id:'comparisons',title:'Compare choices',tamil:'தேர்வுகளை ஒப்பிடுதல்',goal:'Compare options and explain which one is better.',goalTamil:'விருப்பங்களை ஒப்பிட்டு எது சிறந்தது என்று விளக்கவும்.',phrases:[['This phone is cheaper than that one.','இந்த தொலைபேசி அதைவிட மலிவானது.','Comparative'],['The train is more comfortable.','ரயில் அதிக வசதியானது.','Long adjective'],['This is the best option for me.','இது எனக்கு சிறந்த தேர்வு.','Superlative'],['Both choices are reliable.','இரண்டு தேர்வுகளும் நம்பகமானவை.','Show similarity']],note:'Use -er with many short adjectives and “more” with many longer adjectives.',noteTamil:'பல குறுகிய adjectives-க்கு -er; நீளமான adjectives-க்கு “more” பயன்படுத்தவும்.',question:'Choose the correct comparison.',options:['This route is faster.','This route is more fast.'],answer:0,feedback:'Correct! “fast” becomes “faster”.'},
  {id:'phrasal-verbs',title:'Useful phrasal verbs',tamil:'பயனுள்ள phrasal verbs',goal:'Understand common verb combinations in daily speech.',goalTamil:'தினசரி பேச்சில் வரும் பொதுவான verb combinations-ஐ புரிந்துகொள்ளுங்கள்.',phrases:[['Please turn on the light.','தயவுசெய்து விளக்கை ஏற்றுங்கள்.','Switch on'],['I need to find out the time.','நான் நேரத்தைத் தெரிந்துகொள்ள வேண்டும்.','Discover information'],['We ran out of milk.','எங்களிடம் பால் தீர்ந்துவிட்டது.','Have none left'],['Can you pick me up?','என்னை அழைத்துச் செல்ல முடியுமா?','Collect someone']],note:'Learn a phrasal verb as one phrase with its example; its meaning may differ from the individual words.',noteTamil:'Phrasal verb-ஐ உதாரணத்துடன் ஒரே phrase-ஆகக் கற்கவும்; தனிச் சொற்களின் பொருள் வேறுபடலாம்.',question:'“We ran out of water” means…',options:['No water is left.','We carried the water outside.'],answer:0,feedback:'Correct! “run out of” means nothing is left.'},
  {id:'conversation-repair',title:'Keep talking',tamil:'உரையாடலைத் தொடருதல்',goal:'Handle misunderstandings without ending the conversation.',goalTamil:'புரியாமையைச் சமாளித்து உரையாடலைத் தொடருங்கள்.',phrases:[["Sorry, I didn't catch that.",'மன்னிக்கவும், அது எனக்குப் புரியவில்லை.','Signal a problem'],['Could you speak more slowly?','சிறிது மெதுவாகப் பேச முடியுமா?','Request slower speech'],['Do you mean this one?','நீங்கள் இதைத்தான் சொல்கிறீர்களா?','Check meaning'],['Let me say that another way.','அதை வேறு விதமாகச் சொல்கிறேன்.','Rephrase your idea']],note:'Fluent speakers also ask for repetition and clarification; this is a communication skill, not a failure.',noteTamil:'Fluent speakers கூட repetition மற்றும் clarification கேட்பார்கள்; இது தோல்வி அல்ல, communication skill.',question:'You did not understand one word. What can you say?',options:["What does that word mean?",'Stop talking.'],answer:0,feedback:'Correct! Asking for meaning keeps the conversation moving.'},
  {id:'b1-challenge',title:'B1 conversation challenge',tamil:'B1 உரையாடல் சவால்',goal:'Explain an experience, opinion and next step naturally.',goalTamil:'ஒரு அனுபவம், கருத்து மற்றும் அடுத்த படியை இயல்பாக விளக்கவும்.',phrases:[['Last month, I started a new course.','கடந்த மாதம் நான் புதிய பாடத்தைத் தொடங்கினேன்.','Past experience'],['At first, it was difficult.','முதலில், அது கடினமாக இருந்தது.','Describe the beginning'],['However, I am improving now.','ஆனால், நான் இப்போது முன்னேறிக்கொண்டிருக்கிறேன்.','Contrast + present'],['I think I will finish it soon.','நான் அதை விரைவில் முடிப்பேன் என்று நினைக்கிறேன்.','Opinion + future']],note:'At B1, connect ideas across time and add reasons, contrast or examples instead of using isolated sentences.',noteTamil:'B1 நிலையில் தனித்தனி sentences மட்டும் அல்லாமல், காலங்கள், காரணம், contrast, examples ஆகியவற்றை இணைக்கவும்.',question:'Which sentence naturally connects contrast and current progress?',options:['However, I am improving now.','And difficult yesterday.'],answer:0,feedback:'Correct! It connects the earlier difficulty with present progress.'}
];

const b2Lessons = [
  {id:'conditionals',title:'Conditionals',tamil:'நிபந்தனை வாக்கியங்கள்',goal:'Discuss real, possible and imaginary situations.',goalTamil:'உண்மை, சாத்தியம் மற்றும் கற்பனை சூழல்களைப் பேசுங்கள்.',phrases:[['If it rains, we will stay home.','மழை பெய்தால் வீட்டிலேயே இருப்போம்.','Real future possibility'],['If I had more time, I would travel.','எனக்கு அதிக நேரம் இருந்தால் பயணம் செய்வேன்.','Imaginary present'],['If I had known, I would have called.','எனக்குத் தெரிந்திருந்தால் அழைத்திருப்பேன்.','Imaginary past'],['Unless we hurry, we will be late.','நாம் விரையாவிட்டால் தாமதமாகிவிடும்.','Unless = if not']],note:'Conditionals connect a condition with its result; the verb pattern shows how real or imaginary it is.',noteTamil:'Conditionals ஒரு நிபந்தனையையும் அதன் விளைவையும் இணைக்கும்; verb pattern அதன் சாத்தியத்தை காட்டும்.',question:'Which sentence describes an imaginary present?',options:['If I had more money, I would buy it.','If it rains, I will wait.'],answer:0,feedback:'Correct! “If + past, would” describes an imaginary present.'},
  {id:'passive-voice',title:'Passive voice',tamil:'செயப்பாட்டு வினை',goal:'Focus on an action or result when the doer is less important.',goalTamil:'செய்பவர் முக்கியமில்லாதபோது செயல் அல்லது விளைவில் கவனம் செலுத்துங்கள்.',phrases:[['The report was completed yesterday.','அறிக்கை நேற்று முடிக்கப்பட்டது.','Past passive'],['English is spoken worldwide.','ஆங்கிலம் உலகம் முழுவதும் பேசப்படுகிறது.','Present passive'],['The road is being repaired.','சாலை பழுது பார்க்கப்படுகிறது.','Ongoing passive'],['It will be delivered tomorrow.','அது நாளை வழங்கப்படும்.','Future passive']],note:'Form the passive with be + past participle. Mention the doer with “by” only when useful.',noteTamil:'Passive-ஐ be + past participle கொண்டு அமைக்கவும்; தேவைப்பட்டால் மட்டும் “by” உடன் செய்பவரைக் கூறவும்.',question:'Choose the correct passive sentence.',options:['The email was sent yesterday.','The email sent yesterday by itself.'],answer:0,feedback:'Correct! “was sent” is the past passive.'},
  {id:'reported-speech',title:'Reported speech',tamil:'மறைமுகக் கூற்று',goal:'Report what another person said without quoting every word.',goalTamil:'ஒருவர் கூறியதை நேரடியாக மேற்கோள் இல்லாமல் தெரிவியுங்கள்.',phrases:[["She said she was tired.",'அவள் சோர்வாக இருந்ததாகக் கூறினாள்.','Report a statement'],['He told me to wait.','அவர் என்னைக் காத்திருக்கச் சொன்னார்.','Report an instruction'],['They asked if I was ready.','நான் தயாரா என்று அவர்கள் கேட்டார்கள்.','Report a yes/no question'],['She explained that the train was late.','ரயில் தாமதம் என்று அவள் விளக்கினாள்.','Report information']],note:'Reported speech often shifts tense and pronouns because the viewpoint and time have changed.',noteTamil:'பார்வையும் நேரமும் மாறுவதால் reported speech-ல் tense மற்றும் pronoun பொதுவாக மாறும்.',question:'“I am busy,” he said. Which report is natural?',options:['He said he was busy.','He said I am busy.'],answer:0,feedback:'Correct! The viewpoint changes to “he was busy”.'},
  {id:'collocations',title:'Natural word partners',tamil:'இயல்பான சொல் இணைப்புகள்',goal:'Use common collocations so your English sounds natural.',goalTamil:'ஆங்கிலம் இயல்பாக ஒலிக்க பொதுவான collocations பயன்படுத்துங்கள்.',phrases:[['make a decision','முடிவு எடுக்க','Not do a decision'],['take responsibility','பொறுப்பேற்க','Common verb + noun'],['strong evidence','வலுவான ஆதாரம்','Natural adjective + noun'],['highly recommended','மிகவும் பரிந்துரைக்கப்படுகிறது','Natural adverb + adjective']],note:'Collocations are words that commonly occur together; learn the whole combination, not isolated words.',noteTamil:'Collocations வழக்கமாக ஒன்றாக வரும் சொற்கள்; தனிச் சொற்களாக அல்லாமல் முழு combination-ஆகக் கற்கவும்.',question:'Choose the natural collocation.',options:['make progress','do progress'],answer:0,feedback:'Correct! English uses “make progress”.'},
  {id:'presentations',title:'Clear presentations',tamil:'தெளிவான விளக்கவுரை',goal:'Organize a short presentation and guide the audience.',goalTamil:'சிறிய presentation-ஐ ஒழுங்குபடுத்தி பார்வையாளரை வழிநடத்துங்கள்.',phrases:[['Today, I will focus on three points.','இன்று மூன்று அம்சங்களில் கவனம் செலுத்துவேன்.','Preview structure'],['Let us look at the first example.','முதல் உதாரணத்தைப் பார்ப்போம்.','Move to evidence'],['This leads to an important question.','இது ஒரு முக்கிய கேள்விக்கு வழிவகுக்கிறது.','Connect sections'],['To sum up, the results are positive.','சுருக்கமாக, முடிவுகள் நேர்மறையானவை.','Conclude']],note:'Signposting phrases tell listeners where you are and how each idea connects.',noteTamil:'Signposting phrases நீங்கள் எங்கு இருக்கிறீர்கள், கருத்துகள் எவ்வாறு இணைகின்றன என்பதை கேட்பவருக்குக் காட்டும்.',question:'Which phrase introduces a conclusion?',options:['To sum up…','Let me begin with…'],answer:0,feedback:'Correct! “To sum up” signals the conclusion.'},
  {id:'interviews',title:'Interviews & achievements',tamil:'நேர்காணல் மற்றும் சாதனைகள்',goal:'Describe experience and achievements with specific evidence.',goalTamil:'அனுபவம் மற்றும் சாதனைகளை குறிப்பிட்ட ஆதாரத்துடன் விளக்குங்கள்.',phrases:[['I have five years of experience.','எனக்கு ஐந்து ஆண்டு அனுபவம் உள்ளது.','Summarize experience'],['I was responsible for weekly reports.','வாராந்திர அறிக்கைகளுக்கு நான் பொறுப்பாக இருந்தேன்.','Explain responsibility'],['I improved the process by twenty percent.','செயல்முறையை இருபது சதவீதம் மேம்படுத்தினேன்.','Quantify impact'],['That experience taught me to prioritize.','அந்த அனுபவம் முன்னுரிமை அமைக்கக் கற்றுத்தந்தது.','Reflect on learning']],note:'Use a situation, your action and a measurable result to make an interview answer convincing.',noteTamil:'Interview பதில் நம்பகமாக இருக்க situation, உங்கள் action, measurable result ஆகியவற்றைக் கூறவும்.',question:'Which sentence gives measurable impact?',options:['I reduced errors by 15%.','I did many useful things.'],answer:0,feedback:'Correct! A number makes the result specific and credible.'},
  {id:'long-listening',title:'Follow longer speech',tamil:'நீண்ட பேச்சைப் புரிதல்',goal:'Identify structure, key ideas and speaker attitude.',goalTamil:'அமைப்பு, முக்கிய கருத்துகள் மற்றும் பேச்சாளரின் அணுகுமுறையை கண்டறியுங்கள்.',phrases:[['The main point is that demand increased.','முக்கிய கருத்து தேவை அதிகரித்தது என்பதே.','Identify the message'],['For instance, sales rose in June.','உதாரணமாக, ஜூனில் விற்பனை உயர்ந்தது.','Notice evidence'],['On the other hand, costs also grew.','மறுபுறம், செலவுகளும் உயர்ந்தன.','Notice contrast'],['The speaker seems cautiously optimistic.','பேச்சாளர் எச்சரிக்கையான நம்பிக்கையுடன் உள்ளார்.','Infer attitude']],note:'Do not chase every word. Listen for signposts, repeated ideas, examples and changes in tone.',noteTamil:'ஒவ்வொரு சொல்லையும் பின்தொடர வேண்டாம்; signposts, repeated ideas, examples, tone மாற்றங்களை கவனிக்கவும்.',question:'Which phrase usually introduces an example?',options:['For instance…','Nevertheless…'],answer:0,feedback:'Correct! “For instance” introduces an example.'},
  {id:'b2-challenge',title:'B2 communication challenge',tamil:'B2 தொடர்பாடல் சவால்',goal:'Present a balanced view and reach a clear conclusion.',goalTamil:'சமநிலையான கருத்தை முன்வைத்து தெளிவான முடிவுக்கு வாருங்கள்.',phrases:[['There are strong arguments on both sides.','இரு தரப்பிலும் வலுவான வாதங்கள் உள்ளன.','Open a balanced view'],['One advantage is greater flexibility.','ஒரு நன்மை அதிக நெகிழ்வுத்தன்மை.','Develop one side'],['However, this may reduce collaboration.','ஆனால், இது ஒத்துழைப்பைக் குறைக்கலாம்.','Add limitation'],['Overall, a mixed approach seems best.','மொத்தத்தில், கலப்பு அணுகுமுறை சிறந்ததாகத் தெரிகிறது.','Reach a conclusion']],note:'At B2, develop ideas with evidence, acknowledge limitations and make a reasoned conclusion.',noteTamil:'B2 நிலையில் evidence உடன் கருத்தை வளர்த்து, limitations-ஐ ஏற்று, காரணமுள்ள முடிவைக் கூறவும்.',question:'Which sentence gives a balanced conclusion?',options:['Overall, a mixed approach seems best.','This is always perfect.'],answer:0,feedback:'Correct! It gives a measured, reasoned conclusion.'}
];

const c1Lessons = [
  {id:'precision-register',title:'Precision & register',tamil:'துல்லியம் மற்றும் மொழிநடை',goal:'Choose exact words and match formality to the situation.',goalTamil:'துல்லியமான சொற்களைத் தேர்ந்து சூழலுக்கேற்ற formal level பயன்படுத்துங்கள்.',phrases:[['The results indicate a gradual decline.','முடிவுகள் படிப்படியான சரிவைக் காட்டுகின்றன.','Precise formal wording'],['Could you clarify your concern?','உங்கள் கவலையைத் தெளிவுபடுத்த முடியுமா?','Professional request'],["That's a bit of a problem.",'அது சிறிய பிரச்சினையாக இருக்கிறது.','Neutral informal tone'],['The proposal is fundamentally flawed.','முன்மொழிவில் அடிப்படை குறைபாடு உள்ளது.','Strong precise judgement']],note:'Register depends on audience, purpose and relationship; precision depends on the exact meaning you intend.',noteTamil:'Register என்பது audience, purpose, relationship சார்ந்தது; precision என்பது நீங்கள் கூற விரும்பும் சரியான பொருள் சார்ந்தது.',question:'Which phrase is most suitable in a formal report?',options:['The findings indicate…','The stuff shows…'],answer:0,feedback:'Correct! “The findings indicate” is precise and formal.'},
  {id:'complex-clauses',title:'Complex ideas clearly',tamil:'சிக்கலான கருத்துகள் தெளிவாக',goal:'Build complex sentences without losing clarity.',goalTamil:'தெளிவை இழக்காமல் complex sentences அமைக்கவும்.',phrases:[['Although costs rose, profits remained stable.','செலவு உயர்ந்தபோதும் லாபம் நிலையாக இருந்தது.','Concession'],['The policy, which began in June, is working.','ஜூனில் தொடங்கிய கொள்கை செயல்படுகிறது.','Relative clause'],['Having reviewed the data, we changed course.','தரவை ஆய்வு செய்தபின் பாதையை மாற்றினோம்.','Participle clause'],['What matters most is long-term value.','மிக முக்கியமானது நீண்டகால மதிப்பு.','Cleft-like focus']],note:'Complexity is useful only when the relationship between ideas remains obvious.',noteTamil:'கருத்துகளுக்கிடையேயான தொடர்பு தெளிவாக இருந்தால் மட்டுமே complexity பயனுள்ளதாகும்.',question:'Which sentence expresses concession?',options:['Although it was difficult, we succeeded.','Because it was easy, we started.'],answer:0,feedback:'Correct! “Although” contrasts difficulty with success.'},
  {id:'argument-debate',title:'Argument & debate',tamil:'வாதம் மற்றும் விவாதம்',goal:'Build, challenge and refine an argument fairly.',goalTamil:'ஒரு வாதத்தை நியாயமாக அமைத்து, சவால் செய்து, மேம்படுத்துங்கள்.',phrases:[['The evidence supports this position.','ஆதாரம் இந்த நிலைப்பாட்டை ஆதரிக்கிறது.','Support a claim'],['That assumes all users behave alike.','அது எல்லா பயனர்களும் ஒரேபோல் நடப்பதாக கருதுகிறது.','Expose an assumption'],['A possible objection is the cost.','ஒரு எதிர்ப்பு செலவாக இருக்கலாம்.','Acknowledge opposition'],['Even so, the long-term benefit is clear.','அப்படியிருந்தாலும் நீண்டகால நன்மை தெளிவாக உள்ளது.','Respond to objection']],note:'A strong argument distinguishes claims, evidence, assumptions and counterarguments.',noteTamil:'ஒரு வலுவான argument claim, evidence, assumption, counterargument ஆகியவற்றை வேறுபடுத்தும்.',question:'Which sentence challenges an assumption?',options:['That assumes demand will remain constant.','The chart is blue.'],answer:0,feedback:'Correct! It identifies an unstated assumption.'},
  {id:'professional-writing',title:'Professional messages',tamil:'தொழில்முறை எழுத்து',goal:'Write concise, tactful and action-focused messages.',goalTamil:'சுருக்கமான, நயமான மற்றும் action-focused messages எழுதுங்கள்.',phrases:[['I am writing to confirm the revised deadline.','திருத்தப்பட்ட காலக்கெடுவை உறுதிப்படுத்த எழுதுகிறேன்.','State purpose'],['Could you send the final file by Friday?','வெள்ளிக்குள் இறுதி கோப்பை அனுப்ப முடியுமா?','Clear action'],['To avoid delay, please review section two.','தாமதத்தை தவிர்க்க இரண்டாம் பகுதியைப் பாருங்கள்.','Explain reason'],['Please let me know if anything is unclear.','ஏதேனும் தெளிவில்லையெனில் தெரிவிக்கவும்.','Invite clarification']],note:'Put the purpose early, make the requested action explicit and remove unnecessary words.',noteTamil:'Purpose-ஐ ஆரம்பத்திலே கூறி, தேவையான action-ஐ தெளிவுபடுத்தி, தேவையற்ற சொற்களை நீக்கவும்.',question:'Which request is clearest?',options:['Please approve the attached draft by 3 PM Tuesday.','Please do the needful soon.'],answer:0,feedback:'Correct! It states the action and deadline precisely.'},
  {id:'academic-explanation',title:'Explain evidence',tamil:'ஆதாரத்தை விளக்குதல்',goal:'Describe trends, causes and limits in evidence.',goalTamil:'ஆதாரத்தில் trend, cause மற்றும் limitations-ஐ விளக்குங்கள்.',phrases:[['The data shows a steady upward trend.','தரவு நிலையான உயர்வைக் காட்டுகிறது.','Describe a trend'],['This may be partly explained by demand.','இது தேவையால் ஓரளவு விளக்கப்படலாம்.','Careful cause'],['Correlation does not prove causation.','தொடர்பு காரணத்தை நிரூபிக்காது.','State a limitation'],['These findings should be interpreted cautiously.','இந்த முடிவுகளை எச்சரிக்கையுடன் புரிந்துகொள்ள வேண்டும்.','Qualified conclusion']],note:'Academic language separates observation from interpretation and avoids certainty beyond the evidence.',noteTamil:'Academic language observation மற்றும் interpretation-ஐ பிரித்து, evidence-ஐ மீறிய உறுதியைத் தவிர்க்கும்.',question:'Which phrase appropriately limits a conclusion?',options:['The evidence suggests…','This proves everything…'],answer:0,feedback:'Correct! “suggests” matches limited evidence.'},
  {id:'negotiation',title:'Negotiate constructively',tamil:'பயனுள்ள பேச்சுவார்த்தை',goal:'Protect priorities while finding common ground.',goalTamil:'முன்னுரிமைகளை காத்து பொதுவான தீர்வைக் கண்டறியுங்கள்.',phrases:[['Our main priority is delivery time.','எங்கள் முக்கிய முன்னுரிமை வழங்கும் நேரம்.','State an interest'],['We could be flexible on the quantity.','அளவில் நெகிழ்வாக இருக்கலாம்.','Offer movement'],['Would you consider a phased approach?','கட்டப்படியான அணுகுமுறையை பரிசீலிப்பீர்களா?','Propose an option'],['That seems like a reasonable compromise.','அது நியாயமான சமரசமாகத் தெரிகிறது.','Recognize agreement']],note:'Effective negotiation focuses on interests, options and trade-offs rather than fixed positions.',noteTamil:'பயனுள்ள negotiation நிலையான positions அல்லாமல் interests, options, trade-offs மீது கவனம் செலுத்தும்.',question:'Which phrase offers a compromise?',options:['We could extend the deadline if the scope is reduced.','Our position will never change.'],answer:0,feedback:'Correct! It proposes a conditional trade-off.'},
  {id:'fast-speech',title:'Fast natural speech',tamil:'வேகமான இயல்பான பேச்சு',goal:'Recognize reductions, linking and attitude in natural speech.',goalTamil:'இயல்பான பேச்சில் reductions, linking மற்றும் attitude-ஐ கண்டறியுங்கள்.',phrases:[["What are you going to do?",'நீங்கள் என்ன செய்யப் போகிறீர்கள்?','May sound like “whaddaya gonna”'],["I should have told you.",'நான் உங்களிடம் சொல்லியிருக்க வேண்டும்.','May reduce to “should’ve”'],['It depends on what you mean.','நீங்கள் என்ன பொருள் சொல்கிறீர்கள் என்பதைப் பொறுத்தது.','Words link together'],['You might want to reconsider.','நீங்கள் மறுபரிசீலனை செய்யலாம்.','Tone can soften advice']],note:'Train with short audio chunks: predict, listen, check the transcript and repeat with the same rhythm.',noteTamil:'சிறிய audio chunks-ல் predict, listen, transcript check, அதே rhythm-ல் repeat செய்யவும்.',question:'“Should’ve” is the spoken reduction of…',options:['should have','should of'],answer:0,feedback:'Correct! It represents “should have”, not “should of”.'},
  {id:'c1-challenge',title:'C1 communication challenge',tamil:'C1 தொடர்பாடல் சவால்',goal:'Deliver a nuanced recommendation supported by evidence.',goalTamil:'ஆதாரத்துடன் நுணுக்கமான recommendation வழங்குங்கள்.',phrases:[['The evidence is promising, though not conclusive.','ஆதாரம் நம்பிக்கையளிக்கிறது, ஆனால் இறுதியானது அல்ல.','Qualify evidence'],['A full rollout would therefore be premature.','எனவே முழுமையான அறிமுகம் அவசரமானதாக இருக்கும்.','Draw implication'],['I recommend a limited three-month trial.','மூன்று மாத வரையறுக்கப்பட்ட சோதனையை பரிந்துரைக்கிறேன்.','Specific recommendation'],['This would let us test the key assumptions.','இது முக்கிய assumptions-ஐ சோதிக்க உதவும்.','Justify next step']],note:'C1 communication combines precision, qualification, structure and a clear purpose.',noteTamil:'C1 communication precision, qualification, structure மற்றும் தெளிவான purpose-ஐ இணைக்கும்.',question:'Which recommendation is appropriately cautious?',options:['Run a limited trial before full rollout.','Adopt it everywhere immediately.'],answer:0,feedback:'Correct! It matches a promising but uncertain evidence base.'}
];

const c2Lessons = [
  {id:'nuance-implication',title:'Nuance & implication',tamil:'நுணுக்கம் மற்றும் மறைபொருள்',goal:'Understand what speakers imply beyond literal words.',goalTamil:'சொற்களின் நேரடி பொருளைத் தாண்டி பேசுபவர் உணர்த்துவதைப் புரிந்துகொள்ளுங்கள்.',phrases:[["That's one way of looking at it.",'அது ஒரு பார்வை முறை.','May signal polite disagreement'],['The plan is ambitious.','திட்டம் மிகப் பெரிய இலக்கு கொண்டது.','May imply risk in context'],["I wouldn't rule it out.",'அதை முற்றிலும் நிராகரிக்க மாட்டேன்.','Cautious possibility'],['He is not exactly reliable.','அவர் முழுமையாக நம்பகமானவர் அல்ல.','Understated criticism']],note:'Implication comes from context, tone, shared knowledge and what the speaker chooses not to say directly.',noteTamil:'Implication context, tone, shared knowledge மற்றும் நேரடியாகச் சொல்லாதவற்றிலிருந்து வருகிறது.',question:'“That is one way of seeing it” may politely signal…',options:['disagreement','complete certainty'],answer:0,feedback:'Correct! In context it can distance the speaker from the view.'},
  {id:'idiom-style',title:'Idioms & style',tamil:'மரபுத்தொடர்கள் மற்றும் நடை',goal:'Use figurative language selectively and naturally.',goalTamil:'உருவக மொழியைத் தேர்ந்தெடுத்து இயல்பாகப் பயன்படுத்துங்கள்.',phrases:[['We need to read between the lines.','மறைபொருளைப் புரிந்துகொள்ள வேண்டும்.','Infer hidden meaning'],['The idea gained traction.','கருத்து ஆதரவு பெறத் தொடங்கியது.','Became accepted'],['That argument misses the point.','அந்த வாதம் முக்கிய அம்சத்தைத் தவறவிடுகிறது.','Targets wrong issue'],['Let us not lose sight of the goal.','இலக்கை மறந்துவிட வேண்டாம்.','Keep focus']],note:'An idiom should fit the audience and tone; too many idioms make speech less clear, not more fluent.',noteTamil:'Idiom audience மற்றும் tone-க்கு பொருந்த வேண்டும்; அதிக idioms தெளிவைக் குறைக்கும்.',question:'“Read between the lines” means…',options:['infer an unstated meaning','read each line twice'],answer:0,feedback:'Correct! It means infer what is implied.'},
  {id:'humor-culture',title:'Humor & cultural context',tamil:'நகைச்சுவை மற்றும் பண்பாட்டு சூழல்',goal:'Recognize irony, understatement and culture-dependent humor.',goalTamil:'Irony, understatement மற்றும் culture சார்ந்த humor-ஐ புரிந்துகொள்ளுங்கள்.',phrases:[["Well, that went perfectly.",'அது மிகச் சிறப்பாக நடந்தது.','Could be ironic after failure'],["It's a little windy.",'சிறிது காற்றாக இருக்கிறது.','Could understate a storm'],['The timing could have been better.','நேரம் இன்னும் சிறப்பாக இருந்திருக்கலாம்.','Diplomatic criticism'],["You had to be there.",'நீங்கள் அங்கே இருந்தால்தான் புரியும்.','Context-dependent humor']],note:'Never assume humor transfers directly across cultures; read the situation, relationship and tone.',noteTamil:'Humor பண்பாடுகளுக்கு நேரடியாக மாறாது; situation, relationship, tone-ஐ கவனிக்கவும்.',question:'After a disaster, “That went perfectly” is probably…',options:['irony','a literal compliment'],answer:0,feedback:'Correct! Context reverses the literal meaning.'},
  {id:'persuasion',title:'Ethical persuasion',tamil:'நெறிமுறை சார்ந்த தாக்கம்',goal:'Persuade through framing, evidence and audience awareness.',goalTamil:'Framing, evidence மற்றும் audience awareness மூலம் நம்பவையுங்கள்.',phrases:[['The central issue is long-term resilience.','முக்கிய பிரச்சினை நீண்டகால தாங்குதிறன்.','Frame the issue'],['Consider what happens if we delay.','தாமதித்தால் என்ன நடக்கும் என்று பாருங்கள்.','Invite perspective'],['The evidence consistently points one way.','ஆதாரம் தொடர்ந்து ஒரே திசையைக் காட்டுகிறது.','Emphasize evidence'],['This approach serves both priorities.','இந்த அணுகுமுறை இரு முன்னுரிமைகளுக்கும் உதவும்.','Align interests']],note:'Ethical persuasion makes evidence visible, acknowledges uncertainty and respects the audience’s freedom to decide.',noteTamil:'Ethical persuasion evidence-ஐ தெளிவாக காட்டி, uncertainty-ஐ ஏற்று, audience முடிவை மதிக்கும்.',question:'Which approach is ethically persuasive?',options:['Present evidence and acknowledge limitations.','Hide evidence that weakens your claim.'],answer:0,feedback:'Correct! Honest limitations strengthen responsible persuasion.'},
  {id:'adaptive-register',title:'Adapt your voice',tamil:'சூழலுக்கேற்ற மொழிநடை',goal:'Shift register without changing the core message.',goalTamil:'முக்கிய செய்தியை மாற்றாமல் register-ஐ மாற்றுங்கள்.',phrases:[['Could you provide an update at your convenience?','வசதியானபோது update தர முடியுமா?','Formal polite'],['Can you send me an update when you can?','முடிந்தபோது update அனுப்ப முடியுமா?','Neutral'],["Any news when you've got a minute?",'ஒரு நிமிடம் கிடைத்தால் ஏதேனும் செய்தி?','Informal'],['The status remains unchanged.','நிலை மாற்றமின்றி உள்ளது.','Concise formal report']],note:'Expert communication adapts vocabulary, directness, rhythm and detail to the audience.',noteTamil:'Expert communication vocabulary, directness, rhythm, detail ஆகியவற்றை audience-க்கு ஏற்ப மாற்றும்.',question:'Which is most suitable for a formal client email?',options:['Could you provide an update at your convenience?','Hey, any news?'],answer:0,feedback:'Correct! It matches a formal professional relationship.'},
  {id:'critical-synthesis',title:'Synthesize viewpoints',tamil:'பல கருத்துகளை ஒருங்கிணைத்தல்',goal:'Combine sources into a new, balanced understanding.',goalTamil:'பல sources-ஐ புதிய, சமநிலையான புரிதலாக இணைக்கவும்.',phrases:[['Both accounts agree that demand changed.','தேவை மாறியதை இரு அறிக்கைகளும் ஏற்கின்றன.','Identify agreement'],['They differ on the underlying cause.','அடிப்படை காரணத்தில் அவை வேறுபடுகின்றன.','Identify conflict'],['Taken together, the evidence suggests…','ஒன்றாகப் பார்க்கும்போது ஆதாரம் உணர்த்துவது…','Synthesize'],['A remaining uncertainty is timing.','மீதமுள்ள uncertainty நேரம்.','Identify a gap']],note:'Synthesis is not a list of summaries; it compares, connects and evaluates sources to form a larger conclusion.',noteTamil:'Synthesis என்பது summaries பட்டியல் அல்ல; sources-ஐ ஒப்பிட்டு, இணைத்து, மதிப்பிட்டு பெரிய முடிவை உருவாக்கும்.',question:'Which phrase signals synthesis?',options:['Taken together, these findings suggest…','Source one says…'],answer:0,feedback:'Correct! It combines evidence into a broader conclusion.'},
  {id:'spontaneous-fluency',title:'Spontaneous fluency',tamil:'உடனடி சரளப் பேச்சு',goal:'Think aloud, self-correct and develop ideas smoothly.',goalTamil:'யோசித்தபடி பேசி, self-correct செய்து, கருத்தை சீராக வளர்க்கவும்.',phrases:[['Let me think that through.','அதை சற்று யோசிக்கிறேன்.','Hold the floor'],['What I mean is…','நான் சொல்ல வருவது…','Clarify'],['Let me rephrase that.','அதை வேறு விதமாகச் சொல்கிறேன்.','Self-correct'],['There is another aspect worth considering.','கருத்தில் கொள்ள வேண்டிய மற்றொரு அம்சம் உள்ளது.','Extend the idea']],note:'Natural fluency includes pauses and repairs; control matters more than speaking without stopping.',noteTamil:'இயல்பான fluency-ல் pauses மற்றும் repairs இருக்கும்; நிறுத்தமின்றி பேசுவதைவிட control முக்கியம்.',question:'Which phrase helps you correct yourself naturally?',options:['Let me rephrase that.','I cannot speak.'],answer:0,feedback:'Correct! It keeps control while improving the message.'},
  {id:'c2-mastery',title:'C2 mastery challenge',tamil:'C2 நிபுணத்துவ சவால்',goal:'Respond to a complex issue with precision, nuance and style.',goalTamil:'சிக்கலான பிரச்சினைக்கு precision, nuance மற்றும் style உடன் பதிலளிக்கவும்.',phrases:[['The question is less straightforward than it appears.','இந்த கேள்வி தோன்றுவதைவிட சிக்கலானது.','Reframe complexity'],['Much depends on how success is defined.','வெற்றி எவ்வாறு வரையறுக்கப்படுகிறது என்பதில் பல அம்சங்கள் சார்ந்துள்ளன.','Expose a key condition'],['While the short-term case is strong, the broader implications remain uncertain.','குறுகியகால வாதம் வலுவானது; விரிவான விளைவுகள் இன்னும் உறுதியற்றவை.','Balance evidence'],['A proportionate, reversible response would be wiser.','அளவான, திரும்ப மாற்றக்கூடிய பதில் புத்திசாலித்தனமானது.','Nuanced recommendation']],note:'C2 mastery is flexible control: exact meaning, audience fit, coherent structure and effortless reformulation.',noteTamil:'C2 mastery என்பது flexible control: exact meaning, audience fit, coherent structure, effortless reformulation.',question:'Which response shows the most nuance?',options:['The short-term case is strong, but wider effects remain uncertain.','It is completely good.'],answer:0,feedback:'Correct! It balances confidence with uncertainty.'}
];

const levelGrid = document.querySelector('#levelGrid');
levelGrid.innerHTML = levels.map((item, i) => `<button class="level-card" type="button" aria-label="Open ${item.name} course"><div class="level-meta"><span>${item.level}</span><span class="level-number">0${i+1}</span></div><h3>${item.name}</h3><p>${item.desc}</p><div class="level-topics">${item.topics.map(topic => `<span>${topic}</span>`).join('')}</div><span class="level-arrow" aria-hidden="true">↗</span></button>`).join('');

const courses = [
  {key:'a1',levelLabel:'A1 · FOUNDATION',title:'Beginner',summary:'Build the English you need for your first real conversations.',lessons:a1Lessons},
  {key:'a2',levelLabel:'A2 · ELEMENTARY',title:'Everyday English',summary:'Use practical English for daily life, travel, shopping, work and plans.',lessons:a2Lessons},
  {key:'b1',levelLabel:'B1 · INTERMEDIATE',title:'Build your voice',summary:'Connect ideas, tell stories and express opinions with growing confidence.',lessons:b1Lessons},
  {key:'b2',levelLabel:'B2 · UPPER-INTERMEDIATE',title:'Speak with range',summary:'Handle complex grammar, longer speech and professional situations with confidence.',lessons:b2Lessons},
  {key:'c1',levelLabel:'C1 · ADVANCED',title:'Communicate precisely',summary:'Express complex ideas precisely across professional, academic and social settings.',lessons:c1Lessons},
  {key:'c2',levelLabel:'C2 · MASTERY',title:'Fluent & natural',summary:'Control nuance, implication, register and style with expert flexibility.',lessons:c2Lessons}
];
let activeCourseIndex = 0;
let activeLesson = 0;
let practiceAnswered = false;
function activeCourse(){return courses[activeCourseIndex];}
function courseStorageKey(courseKey){return `speakspring-${courseKey}-progress-v1`;}
function readCourseProgress(courseKey=activeCourse().key){try{return JSON.parse(localStorage.getItem(courseStorageKey(courseKey))) || {completed:[]};}catch{return {completed:[]};}}
function writeCourseProgress(progress,courseKey=activeCourse().key){localStorage.setItem(courseStorageKey(courseKey),JSON.stringify(progress));}
function renderLessonList(){
  const course=activeCourse(); const progress=readCourseProgress();
  const lessonList=document.querySelector('#lessonList'); lessonList.setAttribute('aria-label',`${course.levelLabel} lessons`);
  lessonList.innerHTML=course.lessons.map((lesson,i)=>`<button type="button" data-lesson="${i}" class="${i===activeLesson?'active':''} ${progress.completed.includes(lesson.id)?'done':''}"><span class="lesson-list-number">${progress.completed.includes(lesson.id)?'✓':String(i+1).padStart(2,'0')}</span><span class="lesson-list-copy"><b>${lesson.title}</b><small>${lesson.tamil}</small></span><span class="lesson-status">${progress.completed.includes(lesson.id)?'✓':''}</span></button>`).join('');
  document.querySelectorAll('[data-lesson]').forEach(button=>button.addEventListener('click',()=>selectCourseLesson(Number(button.dataset.lesson))));
  const count=progress.completed.length; const percent=Math.round(count/course.lessons.length*100);
  document.querySelector('#courseProgressText').textContent=`${count} of ${course.lessons.length} lessons`;
  document.querySelector('#courseProgressPercent').textContent=`${percent}%`;
  document.querySelector('#courseProgressBar').style.width=`${percent}%`;
}
function selectCourseLesson(index){
  const course=activeCourse(); activeLesson=Math.max(0,Math.min(index,course.lessons.length-1)); practiceAnswered=false;
  const lesson=course.lessons[activeLesson]; const progress=readCourseProgress();
  document.querySelector('#playerLessonNumber').textContent=`LESSON ${String(activeLesson+1).padStart(2,'0')}`;
  document.querySelector('#playerTitle').textContent=lesson.title; document.querySelector('#playerTamilTitle').textContent=lesson.tamil;
  document.querySelector('#playerGoal').textContent=lesson.goal; document.querySelector('#playerGoalTamil').textContent=lesson.goalTamil;
  document.querySelector('#phraseBoard').innerHTML=lesson.phrases.map(phrase=>`<div class="phrase-card"><b>${phrase[0]}</b><span>${phrase[1]}</span><small>${phrase[2]}</small></div>`).join('');
  document.querySelector('#playerNote').textContent=lesson.note; document.querySelector('#playerNoteTamil').textContent=lesson.noteTamil;
  document.querySelector('#checkQuestion').textContent=lesson.question;
  document.querySelector('#checkOptions').innerHTML=lesson.options.map((option,i)=>`<button type="button" data-choice="${i}">${option}</button>`).join('');
  document.querySelector('#checkFeedback').textContent='';
  document.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>answerCoursePractice(Number(button.dataset.choice))));
  const done=progress.completed.includes(lesson.id); const completeButton=document.querySelector('#completeCourseLesson');
  completeButton.disabled=done; completeButton.innerHTML=done?'Lesson completed <span>✓</span>':'Complete lesson <span>✓</span>';
  document.querySelector('#nextCourseLesson').innerHTML=activeLesson===course.lessons.length-1?'Back to first lesson <span>↻</span>':'Next lesson <span>→</span>';
  renderLessonList();
}
function answerCoursePractice(choice){
  if(practiceAnswered)return; practiceAnswered=true; const lesson=activeCourse().lessons[activeLesson];
  document.querySelectorAll('[data-choice]').forEach((button,i)=>{if(i===lesson.answer)button.classList.add('correct');});
  if(choice!==lesson.answer)document.querySelector(`[data-choice="${choice}"]`).classList.add('wrong');
  document.querySelector('#checkFeedback').textContent=choice===lesson.answer?lesson.feedback:`Not quite. ${lesson.feedback}`;
}
function openCourse(courseIndex){
  activeCourseIndex=courseIndex; activeLesson=0; const course=activeCourse();
  document.querySelector('#courseLevelLabel').textContent=course.levelLabel;
  document.querySelector('#courseTitle').textContent=course.title;
  document.querySelector('#courseSummary').textContent=course.summary;
  document.querySelector('#course').hidden=false; selectCourseLesson(0);
  document.querySelector('#course').scrollIntoView({behavior:'smooth',block:'start'});
}
document.querySelectorAll('.level-card').forEach((card,i)=>card.addEventListener('click',()=>{if(i<courses.length){openCourse(i);return;}const arrow=card.querySelector('.level-arrow');arrow.textContent='Soon';setTimeout(()=>arrow.textContent='↗',1500);}));
document.querySelector('#courseBack').addEventListener('click',()=>{document.querySelector('#course').hidden=true;document.querySelector('#path').scrollIntoView({behavior:'smooth'});});
document.querySelector('#completeCourseLesson').addEventListener('click',()=>{const progress=readCourseProgress();const id=activeCourse().lessons[activeLesson].id;if(!progress.completed.includes(id))progress.completed.push(id);writeCourseProgress(progress);selectCourseLesson(activeLesson);updateProgress();});
document.querySelector('#nextCourseLesson').addEventListener('click',()=>{selectCourseLesson((activeLesson+1)%activeCourse().lessons.length);document.querySelector('#coursePlayer').scrollIntoView({behavior:'smooth',block:'start'});});
document.querySelector('#speakLesson').addEventListener('click',()=>{if(!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(activeCourse().lessons[activeLesson].phrases.map(item=>item[0]).join('. '));utterance.lang='en-IN';utterance.rate=.82;const button=document.querySelector('#speakLesson');button.classList.add('speaking');utterance.onend=()=>button.classList.remove('speaking');window.speechSynthesis.speak(utterance);});

const quiz = [
  {question:'Which sentence is correct?', options:['She go to work every day.','She goes to work every day.','She going to work every day.'], answer:1, explanation:'With “he”, “she” or “it” in the simple present, the verb usually takes -s: she goes.'},
  {question:'Choose the natural sentence.', options:['I am interested in music.','I am interested on music.','I interested in music.'], answer:0, explanation:'The natural phrase is “interested in”. Prepositions often belong to a phrase, so learn them together.'},
  {question:'What is the past form of “teach”?', options:['teached','taught','teaching'], answer:1, explanation:'“Teach” is irregular. Its past form is “taught”: I taught my friend yesterday.'}
];
let quizIndex = 0;
let answered = false;
const quizQuestion = document.querySelector('#quizQuestion');
const quizOptions = document.querySelector('#quizOptions');
const quizFeedback = document.querySelector('#quizFeedback');
const quizNext = document.querySelector('#quizNext');
function renderQuiz(){
  const current = quiz[quizIndex]; answered = false;
  document.querySelector('#quizCount').textContent = `${String(quizIndex+1).padStart(2,'0')} / ${String(quiz.length).padStart(2,'0')}`;
  quizQuestion.textContent = current.question;
  quizFeedback.textContent = '';
  quizNext.hidden = true;
  quizOptions.innerHTML = current.options.map((option, i) => `<button class="quiz-option" type="button" data-answer="${i}">${option}</button>`).join('');
  quizOptions.querySelectorAll('button').forEach(button => button.addEventListener('click', () => {
    if(answered) return;
    answered = true;
    const choice = Number(button.dataset.answer);
    quizOptions.querySelectorAll('button').forEach((option, i) => { if(i === current.answer) option.classList.add('correct'); });
    if(choice !== current.answer) button.classList.add('wrong');
    quizFeedback.textContent = `${choice === current.answer ? 'That’s right! ' : 'Not quite. '}${current.explanation}`;
    quizNext.textContent = quizIndex === quiz.length - 1 ? 'Try again ↻' : 'Next question →';
    quizNext.hidden = false;
  }));
}
quizNext.addEventListener('click', () => { quizIndex = (quizIndex + 1) % quiz.length; renderQuiz(); });
document.querySelector('#quizStart').addEventListener('click', () => document.querySelector('#quizCard').scrollIntoView({behavior:'smooth',block:'center'}));
renderQuiz();

const STORAGE_KEY = 'speakspring-progress-v1';
function readProgress(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {lessonDone:false};}catch{return {lessonDone:false};}}
function updateProgress(){
  const progress = readProgress();
  const courseCount=courses.reduce((sum,course)=>sum+readCourseProgress(course.key).completed.length,0);
  const totalLessons=courses.reduce((sum,course)=>sum+course.lessons.length,0);
  const percent = Math.min(100,(progress.lessonDone ? 8 : 0)+Math.round(courseCount/totalLessons*92));
  document.querySelector('#progressPercent').textContent = `${percent}%`;
  document.querySelector('#progressRing').style.background = `conic-gradient(#6552d8 ${percent*3.6}deg,#e4e1f7 ${percent*3.6}deg)`;
  document.querySelector('#progressTitle').textContent = percent ? 'Great start — keep going!' : 'Your journey starts here';
  document.querySelector('#progressText').textContent = courseCount ? `${courseCount} of ${totalLessons} course lessons completed.` : (progress.lessonDone ? 'Your first mini lesson is complete.' : 'Complete your first lesson to begin.');
  document.querySelector('#lessonDone').textContent = progress.lessonDone ? 'Lesson completed ✓' : 'Mark lesson complete ✓';
  document.querySelector('#lessonDone').disabled = progress.lessonDone;
  document.querySelector('#lessonDone').style.opacity = progress.lessonDone ? '.8' : '1';
}
document.querySelector('#lessonDone').addEventListener('click', () => {localStorage.setItem(STORAGE_KEY, JSON.stringify({lessonDone:true})); updateProgress();});
document.querySelector('#continueBtn').addEventListener('click', () => document.querySelector(readProgress().lessonDone ? '#path' : '#lesson').scrollIntoView({behavior:'smooth'}));
document.querySelector('#year').textContent = new Date().getFullYear();
renderLessonList();
updateProgress();
